[[noreturn]] void raise_core(const char* err) { throw std::runtime_error(err); }

ForwardOutput call_forward(int entry, const ForwardInput& in)
{
    InputArena arena;
    const ForwardInputCore c = adapt_input(in, arena);
    ForwardOutputCore out;
    char err[2048];
    if (sweep_call(entry, &c, &out, err, sizeof err)) raise_core(err);
    return to_torch(out, in);
}

BackwardOutput call_backward(int entry, const BackwardInput& in)
{
    InputArena arena;
    const BackwardInputCore c = adapt_input(in, arena);
    BackwardOutputCore out;
    char err[2048];
    if (sweep_call(entry, &c, &out, err, sizeof err)) raise_core(err);
    return to_torch(out, in);
}

RTMOutput call_rtm(int entry, const BackwardInput& in)
{
    InputArena arena;
    const BackwardInputCore c = adapt_input(in, arena);
    RTMOutputCore out;
    char err[2048];
    if (sweep_call(entry, &c, &out, err, sizeof err)) raise_core(err);
    return to_torch(out, in);
}

// A stepped runner: the torch input and the arena its core twin's spans point
// into live here for the handle's life; every run() maps the outputs back.
struct ShimForwardRunner final : IForwardRunner {
    ForwardInput in_;
    InputArena arena_;
    ForwardInputCore core_;
    void* h_ = nullptr;
    ShimForwardRunner(int entry, const ForwardInput& in) : in_(in), core_(adapt_input(in_, arena_))
    {
        char err[2048];
        if (sweep_forward_runner_create(entry, &core_, &h_, err, sizeof err)) raise_core(err);
    }
    ~ShimForwardRunner() override { if (h_) sweep_forward_runner_destroy(h_); }
    ForwardOutput run(int it_begin, int it_end, int step_phase) override
    {
        ForwardOutputCore out;
        char err[2048];
        if (sweep_forward_runner_run(h_, it_begin, it_end, step_phase, &out, err, sizeof err)) raise_core(err);
        return to_torch(out, in_);
    }
    int device_index() const override { return sweep_forward_runner_device_index(h_); }
};

struct ShimBackwardRunner final : IBackwardRunner {
    BackwardInput in_;
    InputArena arena_;
    BackwardInputCore core_;
    void* h_ = nullptr;
    ShimBackwardRunner(int entry, const BackwardInput& in) : in_(in), core_(adapt_input(in_, arena_))
    {
        char err[2048];
        if (sweep_backward_runner_create(entry, &core_, &h_, err, sizeof err)) raise_core(err);
    }
    ~ShimBackwardRunner() override { if (h_) sweep_backward_runner_destroy(h_); }
    BackwardOutput run(int bw_it_begin, int bw_it_end, int step_phase) override
    {
        BackwardOutputCore out;
        char err[2048];
        if (sweep_backward_runner_run(h_, bw_it_begin, bw_it_end, step_phase, &out, err, sizeof err)) raise_core(err);
        return to_torch(out, in_);
    }
    int device_index() const override { return sweep_backward_runner_device_index(h_); }
};

